            Cold(g,r);Witness(g,"initial-"+count);Skip(g);Play(g);Require(Limit(g)==g.State.Players[0].Hp+count*2,"Current marker aggregate contributes to actual HandLimit.");
            // Source identity loss/regrant is a host audit; it does not fabricate a new GameStarting.
            var player=Players(g)[0];var grant=player.SkillGrants.Grants.Single(x=>x.SkillId==Xueyi);player.SkillGrants.RemoveGrant(grant.GrantId);
            Require(Yi(g)==count*2&&Limit(g)==g.State.Players[0].Hp,"HOST: losing enabled lord source preserves marker fact and removes limit.");
            player.SkillGrants.Grant(grant);var role=player.Role;typeof(CharacterState).GetProperty("Role")!.SetValue(player,Role.Rebel);Require(Limit(g)==g.State.Players[0].Hp&&Yi(g)==count*2,"HOST live loss of lord qualification stops marker contribution without clearing facts.");typeof(CharacterState).GetProperty("Role")!.SetValue(player,role);Require(Limit(g)==g.State.Players[0].Hp+count*2,"HOST: restored exact source queries live aggregate.");
        }
        var(god,gr)=Start(god:true);Reach(god,p=>p.Kind==DecisionKind.SelectFaction);Require(!god.Events.Select(e=>e.Payload).OfType<PlayerMarkerChangedEvent>().Any(e=>e.Marker==PlayerMarkerKind.Yi),"Actual god faction selection precedes GameStarting marker facts.");Cold(god,gr);Answer(god,c=>c.Parameters.GetValueOrDefault("faction-id")=="qun");Reach(god,p=>p.SkillPrompt?.SkillId==Xueyi);Require(Yi(god)==4&&god.Events.Select(e=>e.Payload).OfType<GodFactionSelectedEvent>().Single().FactionId=="qun","Actual effective god faction and one other qun participant count as two; two wei participants do not.");Cold(god,gr);Witness(god,"actual-god-mixed-population");
        var(large,larger)=Start(largeMarker:true);Reach(large,p=>p.SkillPrompt?.SkillId==Xueyi);Require(large.Events.Select(e=>e.Payload).OfType<PlayerMarkerChangedEvent>().Any(e=>e.Marker==PlayerMarkerKind.Yi&&e.Delta==24),"Actual generic population multiplier grants24 without old fixed20 cap.");Cold(large,larger);
        var(non,nr)=Start(lord:false);Play(non);Require(Yi(non)==0&&!non.Events.Select(e=>e.Payload).OfType<PlayerMarkerChangedEvent>().Any(e=>e.Marker==PlayerMarkerKind.Yi&&e.PlayerSeat==0),"Actual nonlord printed qualification cannot initialize blood markers.");Cold(non,nr);
        var(dup,dr)=Start();var owner=Players(dup)[0];var source=owner.SkillGrants.Grants.Single(x=>x.SkillId==Xueyi);owner.SkillGrants.Grant(source with{GrantId="host:duplicate",SkillInstanceId="host:duplicate",SourceId="host:duplicate"});Reach(dup,p=>p.SkillPrompt?.SkillId==Xueyi);Require(Yi(dup)==8,"HOST duplicate source before actual start cannot duplicate initial grant.");Skip(dup);Play(dup);Require(dup.Events.Select(e=>e.Payload).OfType<PlayerMarkerChangedEvent>().Count(e=>e.Marker==PlayerMarkerKind.Yi&&e.Delta>0)==1,"One grant across duplicate instance lifecycle.");
        var(frozen,fr)=Start(startPause:true);Reach(frozen,p=>p.SkillPrompt?.SkillId=="fixture:ys-start-pause");var window=frozen.ResolutionStack.OfType<ProgramLifecycleTriggerWindowFrame>().Single(x=>x.Window==SkillProgramTriggerWindow.GameStarting);Require(window.FrozenFactionPopulation!.GetValueOrDefault("qun")==4,"Real owning window freezes population before startup child.");Players(frozen)[1].ChosenFactionId="wei";Skip(frozen);Reach(frozen,p=>p.SkillPrompt?.SkillId==Xueyi);Require(Yi(frozen)==8,"HOST faction mutation inside actual earlier child cannot change frozen population.");Witness(frozen,"host-frozen-population");
    }
    public static void PlayCostExtraChildrenAndCold()
    {
        var(g,r)=Start(gain:true,extra:true);Reach(g,p=>p.SkillPrompt?.SkillId==Xueyi);Skip(g);Play(g);Require(Yi(g)==8,"Decline spends no marker in actual extra Play.");End(g);Reach(g,p=>p.SkillPrompt?.SkillId==Xueyi);var hand=g.State.Players[0].HandCount;Activate(g);Reach(g,p=>p.SkillPrompt?.SkillId=="fixture:ys-gain");Require(Yi(g)==7&&g.State.Players[0].HandCount==hand+1,"Normal Play actual cost1 Draw1 opens real gain child.");Require(Limit(g)==g.State.Players[0].Hp+7,"Paid marker immediately reduces derived limit.");Cold(g,r);Witness(g,"paid-draw-child");Skip(g);Play(g);Require(Yi(g)==7&&g.State.Players[0].HandCount==hand+1,"Child resumes without paying or drawing twice.");Cold(g,r);
        var(lost,lr)=Start(gain:true);Reach(lost,p=>p.SkillPrompt?.SkillId==Xueyi);Activate(lost);Reach(lost,p=>p.SkillPrompt?.SkillId=="fixture:ys-gain");var oldHand=lost.State.Players[0].HandCount;var grant=Players(lost)[0].SkillGrants.Grants.Single(x=>x.SkillId==Xueyi);Players(lost)[0].SkillGrants.RemoveGrant(grant.GrantId);Skip(lost);Play(lost);Require(Yi(lost)==7&&lost.State.Players[0].HandCount==oldHand,"HOST source loss after real Draw preserves paid fact and cancels remaining binding without refund/reissue.");
        var(z,zr)=Start(zeroYi:true);Play(z);Require(Yi(z)==0&&!z.Events.Select(e=>e.Payload).OfType<ProgramBindingStartedEvent>().Any(e=>e.SkillId==Xueyi&&e.BindingId=="spend-yi-draw"),"Actual startup removal makes zero-marker Play offer unaffordable.");Cold(z,zr);
