    public static void ConversionAndActualRemainingTargets()
    {
        foreach(var physical in new[]{false,true})
        {
            var(g,r)=Start(kind:physical?"arrow_barrage":"crossbow");Reach(g,p=>p.SkillPrompt?.SkillId==Xueyi);Skip(g);Play(g);var oldHand=g.State.Players[0].HandCount;
            if(physical)Physical(g);else Convert(g,Luanji);
            Reach(g,p=>p.SkillPrompt?.SkillId==Luanji);Cold(g,r);Witness(g,"exclude-offer-"+physical);for(var seat=1;seat<g.PlayerCount;seat++)Require(g.CreateSnapshot(seat).PendingDecision==null,"Foreign viewers cannot see the exclusion chooser prompt.");Activate(g);var p=P(g)!;var before=GameCheckpointJson.Serialize(g.CreateCheckpoint());var rejected=g.Submit(new AnswerPromptCommand((p.PlayerSeat+1)%g.PlayerCount,p.PromptId,p.Choices[0].Id,g.Revision));Require(!rejected.Accepted&&before==GameCheckpointJson.Serialize(g.CreateCheckpoint()),"Foreign actor rejects atomically.");
            var choice=p.Choices.Last();var target=choice.Targets.Single();Answer(g,c=>c.Id==choice.Id);var use=g.ResolutionStack.OfType<CardUseFrame>().Single(x=>x.CardKind==CardKind.ArrowBarrage);
            Require(use.ArrowBarrageExclusion?.TargetSeat==target&&!use.TargetSeats.Contains(target)&&use.TargetSeats.SequenceEqual(use.Action!.EffectiveDesignatedTargetSeats),"Actual selected target is removed from owning Use and effective Action, with scalar receipt.");
            Require(use.IneffectiveTargetSeats?.Contains(target)!=true,"Removed target is never mislabeled ineffective.");Require(g.Events.Select(e=>e.Payload).OfType<TargetsConfirmedEvent>().Any(e=>e.TargetSeats.Contains(target)),"Original confirmed historical fact keeps initial targets.");Cold(g,r);Witness(g,"excluded-"+physical);Activate(g);Witness(g,"later-observer-selection-"+physical);Require(P(g)!.Choices.All(c=>!c.Targets.Contains(target)),"Actual later finalized observer selects only current remaining targets.");SkipSelectionAndSettle(g);Require(g.Events.Select(e=>e.Payload).OfType<ProgramArrowBarrageTargetRemovedEvent>().Count()==1,"One actual removal.");Require(g.State.Players[0].HandCount==oldHand-(physical?1:2)+1,"Real physical/conversion Hand costs pay once.");Cold(g,r);
            if(!physical)Require(g.Events.Select(e=>e.Payload).OfType<ProgramViewAsConvertedEvent>().Single().PhysicalCardIds.Count==2,"Two Hand conversion pays exact two real entities.");
        }
        var(other,or)=Start(otherConversion:true);Reach(other,p=>p.SkillPrompt?.SkillId==Xueyi);Skip(other);Play(other);Convert(other,"fixture:ys-other-conversion");Reach(other,p=>p.SkillPrompt?.SkillId==Luanji);Activate(other);Answer(other,c=>c.Targets.Count==1);Settle(other);Require(other.Events.Select(e=>e.Payload).OfType<ProgramArrowBarrageTargetRemovedEvent>().Count()==1,"Another conversion source still offers actual actor exclusion.");Cold(other,or);
        var(skip,sr)=Start(kind:"arrow_barrage");Reach(skip,p=>p.SkillPrompt?.SkillId==Xueyi);Skip(skip);Play(skip);Physical(skip);Reach(skip,p=>p.SkillPrompt?.SkillId==Luanji);Skip(skip);Settle(skip);Require(!skip.Events.Select(e=>e.Payload).OfType<ProgramArrowBarrageTargetRemovedEvent>().Any(),"Decline retains all actual targets.");Cold(skip,sr);
    }
    public static void DuplicateLifetimeAndProhibition()
    {
        var(g,r)=Start(kind:"arrow_barrage");Reach(g,p=>p.SkillPrompt?.SkillId==Xueyi);Skip(g);Play(g);var player=Players(g)[0];var grant=player.SkillGrants.Grants.Single(x=>x.SkillId==Luanji);player.SkillGrants.Grant(grant with{GrantId="host:other-luanji",SkillInstanceId="host:other-luanji",SourceId="host:other-luanji"});Physical(g);Reach(g,p=>p.SkillPrompt?.SkillId==Luanji);Activate(g);Answer(g,c=>c.Targets.Count==1);Settle(g);Require(g.Events.Select(e=>e.Payload).OfType<ProgramArrowBarrageTargetRemovedEvent>().Count()==1,"HOST duplicate instances on actual Use share one exclusion scalar.");
        var(lost,lr)=Start(kind:"arrow_barrage");Reach(lost,p=>p.SkillPrompt?.SkillId==Xueyi);Skip(lost);Play(lost);Physical(lost);Reach(lost,p=>p.SkillPrompt?.SkillId==Luanji);Activate(lost);var lostGrant=Players(lost)[0].SkillGrants.Grants.Single(x=>x.SkillId==Luanji);Players(lost)[0].SkillGrants.RemoveGrant(lostGrant.GrantId);Answer(lost,c=>c.Targets.Count==1);Settle(lost);Require(!lost.Events.Select(e=>e.Payload).OfType<ProgramArrowBarrageTargetRemovedEvent>().Any(),"HOST source disappearance before removal keeps actual target set.");
        var(ban,br)=Start(kind:"arrow_barrage",ban:true);Reach(ban,p=>p.SkillPrompt?.SkillId==Xueyi);Skip(ban);Play(ban);Require(!ban.GetHumanLegalActions().Any(a=>a.Kind==LegalActionKind.ArrowBarrage||a.ProgramSkillId==Luanji),"Real pre-issue Use prohibition remains effective despite post-issue exclusion capability.");Cold(ban,br);
        var(actor,ar)=Start(kind:"arrow_barrage");Reach(actor,p=>p.SkillPrompt?.SkillId==Xueyi);Skip(actor);Play(actor);Physical(actor);Reach(actor,p=>p.SkillPrompt?.SkillId==Luanji);Activate(actor);Answer(actor,c=>c.Targets.Count==1);var actual=actor.ResolutionStack.OfType<CardUseFrame>().Single(x=>x.CardKind==CardKind.ArrowBarrage);var changed=actual with{SourceSeat=1,Action=new CardActionContext(actual.Action!.ActionId,actual.Action.ParentActionId,actual.Action.Type,1,actual.Action.ProviderSeat,actual.Action.RequesterSeat,actual.Action.ResponderSeat,actual.Action.OpponentSeat,actual.Action.EffectiveKind,actual.TargetSeats,actual.Action.PhysicalCards,actual.Action.ConversionChain,actual.TargetSeats,actual.Action.EffectiveSuit,actual.Action.EffectiveRank)};typeof(GameEngine).GetMethod("UpdateProgramRoleCardUse",BindingFlags.NonPublic|BindingFlags.Instance)!.Invoke(actor,[changed,changed.Action!]);Require(changed.ArrowBarrageExclusion==actual.ArrowBarrageExclusion,"HOST legal actor rewrite preserves owning one-use receipt.");Settle(actor);Require(actor.Events.Select(e=>e.Payload).OfType<ProgramArrowBarrageTargetRemovedEvent>().Count()==1,"HOST rewritten actual Use cannot remove a second target.");
    }
    public static void ZeroTargetsNativeAndCompatibility()
    {
        foreach(var converted in new[]{false,true})
        {
            var(g,r)=Start(kind:converted?"nullification":"arrow_barrage",singleTarget:true,jizhi:true);Reach(g,p=>p.SkillPrompt?.SkillId==Xueyi);Skip(g);Play(g);var initial=g.State.Players[0].HandCount;if(converted)Convert(g,Luanji);else Physical(g);Reach(g,p=>p.SkillPrompt?.SkillId==Luanji);Activate(g);Answer(g,c=>c.Targets.Count==1);var use=g.ResolutionStack.OfType<CardUseFrame>().Single(x=>x.CardKind==CardKind.ArrowBarrage);Require(use.TargetSeats.Count==0&&use.Action!.TargetSeats.Count==0,"Actual final target may be removed to zero.");Cold(g,r);Witness(g,"zero-targets-"+converted);if(converted){Skip(g);Reach(g,p=>p.Kind==DecisionKind.Nullification&&p.PlayerSeat==0);Cold(g,r);Witness(g,"zero-real-nullification-offer");var paid=P(g)!.Choices.First(c=>c.Cards.Count==1).Cards.Single();Answer(g,c=>c.Cards.SequenceEqual([paid]));Settle(g);Require(g.CardMovements.Count(m=>m.CardId==paid&&m.From==CardLocation.Hand(0)&&m.To==CardLocation.Processing)==1,"Actual zero-target Nullification entity pays once.");}else Settle(g);Require(!g.Events.Select(e=>e.Payload).OfType<DamageAppliedEvent>().Any(),"Zero-target Use has no response attack or damage.");Require(g.Events.Select(e=>e.Payload).OfType<CardUseFinishedEvent>().Count(e=>e.CardKind==CardKind.ArrowBarrage)==1,"Zero-target actual Use finitely completes once through typed parent.");Require(g.Events.Select(e=>e.Payload).OfType<ProgramBindingStartedEvent>().Any(e=>e.SkillId=="classic:jizhi"),"Zero-target actual Use retains real Jizhi.");Require(g.State.Players[0].HandCount>=initial-(converted?2:1),"Zero-target real Jizhi retains original paid cost.");Cold(g,r);Witness(g,"zero-finished-"+converted);
        }
        var(n,nr)=Start(native:true,kind:"arrow_barrage");for(var i=0;i<130&&n.Events.Select(e=>e.Payload).OfType<ProgramArrowBarrageTargetRemovedEvent>().Count()==0;i++)Drive(n);Require(n.Events.Select(e=>e.Payload).OfType<ProgramArrowBarrageTargetRemovedEvent>().Any(),"Formal native optional AI makes an actual exclusion based on public ally harm.");Cold(n,nr);Witness(n,"formal-native-exclusion");
        var rules=Read("rules");var presentation=Read("presentation");foreach(var bad in new[]{rules.Replace("\"multiplier\": 2","\"multiplier\": -1"),rules.Replace("\"valueMarker\": \"yi\"","\"valueMarker\": null"),rules.Replace("currentArrowBarrageTargets","currentCardUseTargets"),rules.Replace("cardUseTargetsFinalized","cardUseBeforeTargetEffects")}){var rejected=false;try{SkillProgramCatalog.Load(bad,presentation);}catch(InvalidOperationException){rejected=true;}Require(rejected,"New population/exclusion/marker resources reject malformed contexts.");}
        var old=new CardUseFrame(1,0,1,CardKind.ArrowBarrage,[1]);Require(!JsonSerializer.Serialize(old).Contains("ArrowBarrageExclusion"),"Legacy nullable card-use shape stays absent.");var modifier=SkillProgramCatalog.Load(Read("rules"),presentation).Programs[Xueyi].Modifiers.Single();Require(modifier.QueryDependencies.SequenceEqual([SkillRuleQueryDependency.MarkerState]),"Owner marker numeric query declares exact dependency.");
    }
    static int Limit(GameEngine g)=>(int)typeof(GameEngine).GetMethod("GetHandLimit",BindingFlags.NonPublic|BindingFlags.Instance)!.Invoke(g,[Players(g)[0]])!;
    static int Yi(GameEngine g)=>g.CreateSnapshot(0).Players[0].Markers?.Where(m=>m.Kind==PlayerMarkerKind.Yi).Sum(m=>m.Count)??0;
    static PendingDecision? P(GameEngine g)=>g.PendingDecision??Enumerable.Range(0,g.PlayerCount).Select(s=>g.CreateSnapshot(s,true).PendingDecision).FirstOrDefault(p=>p!=null);
    static CharacterState[] Players(GameEngine g)=>((IReadOnlyList<CharacterState>)typeof(GameEngine).GetField("_players",BindingFlags.NonPublic|BindingFlags.Instance)!.GetValue(g)!).ToArray();
    static void Activate(GameEngine g)=>Answer(g,c=>c.Parameters.GetValueOrDefault("program-action")=="activate");
    static void Skip(GameEngine g)=>Answer(g,c=>c.Parameters.GetValueOrDefault("program-action")=="skip");
    static void Answer(GameEngine g,Func<PromptChoice,bool> predicate){var p=P(g)!;Accept(g,new AnswerPromptCommand(p.PlayerSeat,p.PromptId,p.Choices.First(predicate).Id,g.Revision));}
    static void Reach(GameEngine g,Func<PendingDecision,bool> goal){for(var i=0;i<160;i++){if(P(g)is{}p&&goal(p))return;Drive(g);}throw new InvalidOperationException("Missing actual boundary: "+P(g)?.Prompt);}
    static void Play(GameEngine g)=>Reach(g,p=>p.Kind==DecisionKind.PlayCard&&p.PlayerSeat==0);
    static void End(GameEngine g)=>Accept(g,new EndPlayPhaseCommand(0,g.Revision,P(g)!.PromptId));
    static void Drive(GameEngine g)
    {
        if(P(g)is{}p&&p.PlayerSeat==g.State.HumanSeat){if(p.Kind==DecisionKind.PlayCard)Accept(g,new EndPlayPhaseCommand(p.PlayerSeat,g.Revision,p.PromptId));else Answer(g,c=>c.Parameters.GetValueOrDefault("program-action")=="skip"||c.Cards.Count==0);}
        else Accept(g,new AdvanceOneStepCommand(g.Revision));
    }
    static void Settle(GameEngine g){for(var i=0;i<160;i++){if(P(g)is{Kind:DecisionKind.PlayCard,PlayerSeat:0})return;Drive(g);}throw new InvalidOperationException("Use did not finitely return to actual Play.");}
    static void SkipSelectionAndSettle(GameEngine g){Answer(g,c=>c.Targets.Count==1);Settle(g);}
    static void Physical(GameEngine g){var action=g.GetHumanLegalActions().First(a=>a.Kind==LegalActionKind.ArrowBarrage);Accept(g,new PlayCardCommand(0,action.CardId!.Value,action.SelectableTargetSeats??[],g.Revision,P(g)!.PromptId));}
    static void Convert(GameEngine g,string skill){var ids=g.State.Players[0].Hand.Take(2).Select(c=>c.Id).ToArray();Accept(g,new UseProgramSkillCommand(0,skill,Conversion,ids,[],g.Revision,P(g)!.PromptId));}
    static void Accept(GameEngine g,GameCommand command)
    {
        var before=GameCheckpointJson.Serialize(g.CreateCheckpoint());try{var result=g.Submit(CommandJson.Deserialize(CommandJson.Serialize([command])).Single());Require(result.Accepted,result.Error?.Message??"Rejected actual command.");}
        catch(Exception ex){if(Environment.GetEnvironmentVariable("CARD_YS_EVIDENCE") is{Length:>0}path){var d=Path.Combine(path,"actual-exception-"+(++EvidenceSequence));Directory.CreateDirectory(d);File.WriteAllText(Path.Combine(d,"checkpoint-before.json"),before);File.WriteAllText(Path.Combine(d,"attempt-command.json"),CommandJson.Serialize([command]));File.WriteAllText(Path.Combine(d,"trusted-observed-stack.json"),JsonSerializer.Serialize(g.ResolutionStack));File.WriteAllText(Path.Combine(d,"exception.txt"),ex.ToString());}throw;}
    }
    static void Cold(GameEngine g,ContentRegistry r){var restored=GameReplay.Restore(GameCheckpointJson.Deserialize(GameCheckpointJson.Serialize(g.CreateCheckpoint())),r);Require(CommandJson.Serialize(restored.AcceptedCommands)==CommandJson.Serialize(g.AcceptedCommands),"Cold prefix retains exact accepted commands.");for(var s=0;s<g.PlayerCount;s++)Require(SnapshotJson.Serialize(restored.CreateSnapshot(s))==SnapshotJson.Serialize(g.CreateSnapshot(s)),"Every viewer's cold public/private projection matches.");Require(g.CreateCardZoneDiagnostics().Select(x=>x.CardId).Distinct().Count()==g.CreateCardZoneDiagnostics().Count,"Physical entities conserved.");}
    static void Witness(GameEngine g,string label){if(Environment.GetEnvironmentVariable("CARD_YS_EVIDENCE") is not{Length:>0}path)return;var d=Path.Combine(path,label);Directory.CreateDirectory(d);File.WriteAllText(Path.Combine(d,"checkpoint.json"),GameCheckpointJson.Serialize(g.CreateCheckpoint()));File.WriteAllText(Path.Combine(d,"trusted-stack.json"),JsonSerializer.Serialize(g.ResolutionStack));for(var s=0;s<Math.Min(g.PlayerCount,4);s++)File.WriteAllText(Path.Combine(d,"view-"+s+".json"),SnapshotJson.Serialize(g.CreateSnapshot(s)));}
    static void Require(bool condition,string message){if(!condition)throw new InvalidOperationException(message);}
    static string Read(string type){using var stream=typeof(StandardContentPackage).Assembly.GetManifestResourceStream("CardGame.Content.Standard.SkillPrograms.boundary-yuan-shao."+type+".json")!;using var reader=new StreamReader(stream);return reader.ReadToEnd();}
