    static (GameEngine,ContentRegistry) Start(int count=4,bool lord=true,bool startPause=false,bool gain=false,bool extra=false,bool zeroYi=false,string kind="crossbow",bool otherConversion=false,bool ban=false,bool singleTarget=false,bool jizhi=false,bool native=false,bool god=false,bool largeMarker=false)
