            if(gain)Add("fixture:ys-gain","\"triggers\":[{\"id\":\"pause\",\"window\":\"cardsGained\",\"subject\":\"owner\",\"destinationZones\":[\"hand\"],\"movementOccurrence\":\"perBatch\",\"optional\":true,\"effects\":[{\"op\":\"selectOwnedCards\",\"target\":\"owner\",\"zones\":[\"hand\"],\"amount\":1,\"resultBind\":\"selected\"},{\"op\":\"moveBoundCards\",\"target\":\"owner\",\"sourceBind\":\"selected\",\"destination\":\"discardPile\"}]}]");
