            if(ban)Add("fixture:ys-ban","\"triggers\":[{\"id\":\"ban\",\"window\":\"playPhaseStarting\",\"subject\":\"owner\",\"optional\":false,\"priority\":100,\"effects\":[{\"op\":\"grantTurnCardActionProhibition\",\"target\":\"owner\",\"cardKinds\":[\"arrowBarrage\"],\"actionTypes\":[\"use\"]}]}]");
            if(otherConversion){var catalog=SkillProgramCatalog.Load(Read("rules").Replace(Luanji,"fixture:ys-other-conversion"),Read("presentation").Replace(Luanji,"fixture:ys-other-conversion"));b.AddSkill(new("fixture:ys-other-conversion","other","fixture"){Program=catalog.Programs["fixture:ys-other-conversion"]});extras.Add("fixture:ys-other-conversion");}
            if(singleTarget)Add("fixture:ys-shield","\"cardPolicies\":[{\"id\":\"avoid-arrow\",\"kind\":\"prohibitTarget\",\"cardKinds\":[\"arrowBarrage\"]}]",false);
            b.AddGeneral(new("fixture:ys-owner","主公","supporter",Luanji,god?"god":"qun",8,extras));
            for(var i=1;i<count;i++)b.AddGeneral(new("fixture:ys-target-"+i,"目标"+i,"supporter",native||!lord?Luanji:"standard:none",god&&i>1?"wei":"qun",8,!lord?[Xueyi]:singleTarget&&i>1?["fixture:ys-shield"]:[]));
            b.AddDeck(new("fixture:ys-deck","固定",4,0,[]){PhysicalCards=Enumerable.Range(0,count*30).Select(i=>new ContentDeckPhysicalCard("standard:"+kind,Suit.Spade,i%13+1)).ToArray()});
            b.AddMode(new("identity:classic-ys-check","固定",count,count,new Dictionary<string,int>{{nameof(Role.Lord),1},{nameof(Role.Loyalist),1},{nameof(Role.Rebel),count-2}},"fixture:ys-deck",GeneralCandidateCount:count,GeneralPoolIds:new[]{"fixture:ys-owner"}.Concat(Enumerable.Range(1,count-1).Select(i=>"fixture:ys-target-"+i)).ToArray()));
        }
